import { FormEvent, useState } from 'react'
import './App.css'

type Task = {
    id: number
    title: string
    completed: boolean
}

function App() {
    const [tasks, setTasks] = useState<Task[]>([])
    const [newTask, setNewTask] = useState('')

    function addTask(event: FormEvent<HTMLFormElement>) {
        event.preventDefault()
        const title = newTask.trim()

        if (!title) {
            return
        }

        setTasks((currentTasks) => [
            ...currentTasks,
            { id: Date.now(), title, completed: false },
        ])
        setNewTask('')
    }

    function toggleTask(id: number) {
        setTasks((currentTasks) =>
            currentTasks.map((task) =>
                task.id === id ? { ...task, completed: !task.completed } : task,
            ),
        )
    }

    function removeTask(id: number) {
        setTasks((currentTasks) => currentTasks.filter((task) => task.id !== id))
    }

    const completedTasks = tasks.filter((task) => task.completed).length

    return (
        <main className="app">
            <section className="todo-card" aria-labelledby="page-title">
                <header className="todo-header">
                    <p className="eyebrow">ORGANIZAÇÃO</p>
                    <h1 id="page-title">Minha lista de tarefas</h1>
                    <p className="summary">
                        {completedTasks} de {tasks.length} tarefa(s) concluída(s)
                    </p>
                </header>

                <form className="task-form" onSubmit={addTask}>
                    <label className="sr-only" htmlFor="new-task">
                        Nova tarefa
                    </label>
                    <input
                        id="new-task"
                        type="text"
                        value={newTask}
                        onChange={(event) => setNewTask(event.target.value)}
                        placeholder="Digite uma nova tarefa"
                    />
                    <button type="submit">Adicionar</button>
                </form>

                {tasks.length === 0 ? (
                    <p className="empty-state">Você ainda não tem tarefas. Adicione a primeira!</p>
                ) : (
                    <ul className="task-list">
                        {tasks.map((task) => (
                            <li className="task-item" key={task.id}>
                                <label className={task.completed ? 'task completed' : 'task'}>
                                    <input
                                        type="checkbox"
                                        checked={task.completed}
                                        onChange={() => toggleTask(task.id)}
                                    />
                                    <span>{task.title}</span>
                                </label>
                                <button
                                    className="remove-button"
                                    type="button"
                                    onClick={() => removeTask(task.id)}
                                    aria-label={`Remover tarefa ${task.title}`}
                                >
                                    Remover
                                </button>
                            </li>
                        ))}
                    </ul>
                )}
            </section>
        </main>
    )
}

export default App
